wire signed [31:0] _mul67 = _t37 * (_t38 - _s3_w);
wire signed [15:0] _t39 = (_mul67 >>> 8);
wire signed [15:0] _k4_w = _t39;
wire signed [18:0] _rkw_v = _k1_v + _k2_v + _k2_v + _k3_v + _k3_v + _k4_v;
wire signed [34:0] _rk6mul_v = _rkw_v * 16'sd4;
wire signed [18:0] _rkw_w = _k1_w + _k2_w + _k2_w + _k3_w + _k3_w + _k4_w;
wire signed [34:0] _rk6mul_w = _rkw_w * 16'sd4;

wire signed [15:0] dv = (_rk6mul_v >>> 8);
wire signed [15:0] dw = (_rk6mul_w >>> 8);

wire signed [16:0] v_raw = v_reg + dv;
wire signed [15:0] v_next = (v_raw > 17'sd32767) ? 16'sd32767 : (v_raw < (-17'sd32768)) ? (-16'sd32768) : v_raw[15:0];
wire signed [16:0] w_raw = w_reg + dw;
wire signed [15:0] w_next = (w_raw > 17'sd32767) ? 16'sd32767 : (w_raw < (-17'sd32768)) ? (-16'sd32768) : w_raw[15:0];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        v_reg <= 16'sd50176;
        v_out <= 16'sd50176;
        w_reg <= 16'sd0;
        w_out <= 16'sd0;
        spike_out <= 1'b0;
        _thr_prev <= 1'b0;
    end else begin
        if (((v_next >= P_V_THRESHOLD)) && !_thr_prev) begin
            spike_out <= 1'b1;
            v_reg <= v_next;
            w_reg <= w_next;
            v_out <= v_reg;
            w_out <= w_reg;
        end else begin
            spike_out <= 1'b0;
            v_reg <= v_next;
            v_out <= v_next;
            w_reg <= w_next;
            w_out <= w_next;
        end
        _thr_prev <= ((v_next >= P_V_THRESHOLD));
    end
end

